algorithms.pseudocode:
Input: Finite poset M, residuated action (act, res) indexed by H
Output: For each h in H, the set Closed(h)

for h in H:
    Closed(h) <- {}
    for x in M:
        if res(h, act(h, x)) == x:
            Closed(h) <- Closed(h) ∪ {x}
    output Closed(h)

Time: O(|H| * |M|), Space: O(|H| * |M|)

Input: Finite poset M, list of residuated actions, bottom element bot
Output: Set of simple summands

S <- {}
for x in M \ {bot}:
    if forall h: cl_h(x) == x:              # closed under all
        if forall h, forall y: (x <= cl_h(y) => x <= y):  # closure-prime
            S <- S ∪ {x}
output S

Time: O(|H| * |M|^2), Space: O(|M|)
